<?php require '../includes/db.php';require '../includes/functions.php';if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['qty']??[] as $id=>$q){$id=(int)$id;$q=(int)$q;$s=$conn->prepare('SELECT stock FROM books WHERE id=?');$s->bind_param('i',$id);$s->execute();$bk=$s->get_result()->fetch_assoc();if(!$bk||$q<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($q,(int)$bk['stock']);}}$cart=$_SESSION['cart']??[];$items=[];$total=0;foreach($cart as $id=>$qty){$s=$conn->prepare('SELECT * FROM books WHERE id=?');$s->bind_param('i',$id);$s->execute();if($x=$s->get_result()->fetch_assoc()){$x['qty']=$qty;$total+=$x['price']*$qty;$items[]=$x;}}$page_title='Cart';include '../includes/header.php';?><h1>Shopping Cart</h1><?php if(!$items):?><p>Cart is empty. <a href="../">Browse books</a>.</p><?php else:?><form method="post"><div class="tablewrap"><table><tr><th>Book</th><th>Price</th><th>Qty</th><th>Remove</th></tr><?php foreach($items as $x):?><tr><td><?=e($x['title'])?></td><td><?=cash($x['price'])?></td><td><input type="number" min="0" max="<?=$x['stock']?>" name="qty[<?=$x['id']?>]" value="<?=$x['qty']?>"></td><td><a href="remove.php?id=<?=$x['id']?>">Remove</a></td></tr><?php endforeach;?></table></div><h2>Total: <?=cash($total)?></h2><button class="btn">Update Cart</button> <a class="btn" href="../checkout.php">Checkout</a></form><?php endif;?><?php include '../includes/footer.php';?>
